import React from 'react';
import { motion } from 'framer-motion';



export const OrderStatusDisplay = ({ status }) => {
    const steps = [
        { id: 'placed', label: 'Order Placed', icon: 'ri-checkbox-circle-line' },
        { id: 'preparing', label: 'Preparing', icon: 'ri-restaurant-line' },
        { id: 'on_the_way', label: 'On the Way', icon: 'ri-truck-line' },
        { id: 'delivered', label: 'Delivered', icon: 'ri-home-heart-line' }
    ];

    const currentStepIndex = steps.findIndex(s => s.id === status);

    return (
        <div className="w-full py-8">
            <div className="relative">
                {/* Progress Line */}
                <div className="absolute top-8 left-0 right-0 h-1 bg-gold/20">
                    <motion.div
                        className="h-full bg-gradient-to-r from-gold to-[#D4AF37]"
                        initial={{ width: '0%' }}
                        animate={{ width: `${(currentStepIndex / (steps.length - 1)) * 100}%` }}
                        transition={{ duration: 1, delay: 0.5 }}
                    />
                </div>

                {/* Stages */}
                <div className="relative flex justify-between">
                    {steps.map((step, index) => (
                        <motion.div
                            key={step.id}
                            className="flex flex-col items-center"
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: 0.3 + index * 0.1 }}
                        >
                            <motion.div
                                className={`w-16 h-16 rounded-full flex items-center justify-center mb-3 transition-colors duration-300 ${index <= currentStepIndex
                                    ? 'bg-gradient-to-r from-gold to-[#D4AF37]'
                                    : 'bg-[#140B07] border border-gold/20'
                                    }`}
                                animate={index === currentStepIndex ? {
                                    scale: [1, 1.1, 1],
                                    boxShadow: [
                                        '0 0 0 0 rgba(197, 160, 33, 0.7)',
                                        '0 0 0 20px rgba(197, 160, 33, 0)',
                                        '0 0 0 0 rgba(197, 160, 33, 0)'
                                    ]
                                } : {}}
                                transition={{ duration: 2, repeat: Infinity }}
                            >
                                <i className={`${step.icon} text-2xl ${index <= currentStepIndex ? 'text-obsidian' : 'text-cream/50'}`}></i>
                            </motion.div>
                            <p className={`font-outfit text-xs sm:text-sm text-center font-medium ${index <= currentStepIndex ? 'text-cream' : 'text-cream/50'
                                }`}>
                                {step.label}
                            </p>
                        </motion.div>
                    ))}
                </div>
            </div>

            <div className="mt-12 text-center">
                <motion.p
                    key={status}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="text-gold font-outfit text-sm"
                >
                    {status === 'placed' && "We've received your order!"}
                    {status === 'preparing' && "Our chefs are crafting your desserts..."}
                    {status === 'on_the_way' && "Your treats are on their way to you!"}
                    {status === 'delivered' && "Enjoy your Chocolate Room experience!"}
                </motion.p>
            </div>
        </div>
    );
};
