import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useParams } from 'react-router-dom';
import { useOrder } from '../../context/OrderContext';
import { OrderStatusDisplay } from './OrderStatusDisplay';
import ResponsiveImage from '../../components/ResponsiveImage';
import { SpriteImage } from '../../components/SpriteImage';

const foodFacts = [
  "Did you know? Chocolate was used as currency in Aztec times. 🍫",
  "The smell of chocolate increases theta brain waves, which triggers relaxation. ✨",
  "White chocolate isn't technically chocolate because it contains no cocoa solids! 🥛",
  "A single chocolate chip gives enough energy for an adult to walk 150 feet. 🚶",
  "Chocolate contains phenylethylamine, the same chemical your brain creates when you're in love. ❤️",
  "The average Swiss person eats about 20 pounds of chocolate per year! 🇨🇭",
  "It takes approximately 400 cocoa beans to make one pound of chocolate. 🌰",
  "Milk chocolate was actually invented in Switzerland by Daniel Peter. 🥛"
];

export default function TrackOrder() {
  const { orderId } = useParams();
  const { activeOrder, updateOrderStatus } = useOrder();
  const [currentFact, setCurrentFact] = useState(0);

  // Status progression simulation
  useEffect(() => {
    if (!activeOrder) return;

    const sequence = {
      'placed': 'preparing',
      'preparing': 'on_the_way',
      'on_the_way': 'delivered'
    };

    const interval = setInterval(() => {
      if (activeOrder.status !== 'delivered') {
        updateOrderStatus(sequence[activeOrder.status]);
      }
    }, 15000); // Progress every 15 seconds for demo

    return () => clearInterval(interval);
  }, [activeOrder?.status]);

  // Food facts interval
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentFact(prev => (prev + 1) % foodFacts.length);
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  if (!activeOrder) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-[#0A0604] via-[#140B07] to-[#25160F] flex items-center justify-center pt-24">
        <div className="text-center px-8">
          <div className="w-20 h-20 bg-gold/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-gold/20">
            <i className="ri-error-warning-line text-4xl text-gold"></i>
          </div>
          <h2 className="font-syncopate text-2xl text-[#F8F4F0] mb-4">No Active Order</h2>
          <p className="font-outfit text-[#F8F4F0]/60 mb-8 max-w-sm">
            We couldn't find any live order associated with your session.
          </p>
          <button
            onClick={() => window.REACT_APP_NAVIGATE('/')}
            className="px-8 py-4 bg-gradient-to-r from-gold to-[#D4AF37] text-obsidian font-syncopate font-bold text-xs rounded-full cursor-pointer"
          >
            GO TO HOME
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#0A0604] via-[#140B07] to-[#25160F] pt-24 pb-20 overflow-x-hidden">
      <div className="max-w-7xl mx-auto px-6">
        <div className="grid lg:grid-cols-2 lg:gap-12">
          {/* Left Column, Time, Status */}
          <div>
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
              <button
                onClick={() => window.REACT_APP_NAVIGATE('/')}
                className="w-10 h-10 bg-white/5 rounded-full flex items-center justify-center border border-white/10 text-gold hover:bg-white/10 transition-colors"
                title="Back to Home"
              >
                <i className="ri-arrow-left-line text-lg"></i>
              </button>
              <div className="text-center">
                <h1 className="font-syncopate text-xs text-gold/60 tracking-[0.2em] mb-1">TRACKING ORDER</h1>
                <p className="font-syncopate text-sm text-[#F8F4F0] font-bold">#{orderId?.substring(0, 8)}</p>
              </div>
              <div className="w-10 h-10" /> {/* Spacer */}
            </div>

            {/* Time Card */}
            <motion.div
              className="glass-panel-strong rounded-3xl p-8 border border-gold/20 mb-8 relative overflow-hidden text-center"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
            >
              <div className="absolute top-0 right-0 w-32 h-32 bg-gold/5 blur-3xl -mr-16 -mt-16" />
              <p className="font-outfit text-gold/60 text-xs mb-2 uppercase tracking-widest">Estimated Delivery</p>
              <h2 className="font-syncopate text-5xl text-[#F8F4F0] font-bold mb-2">25-30</h2>
              <p className="font-syncopate text-sm text-gold">MINUTES</p>
            </motion.div>

            {/* Status Display */}
            <div className="mb-12 lg:mb-0">
              <OrderStatusDisplay status={activeOrder.status} />
            </div>
          </div>

          {/* Right Column, Facts, Contact */}
          <div className="space-y-8">
            {/* Order Items */}
            <motion.div
              className="glass-panel rounded-3xl p-6 border border-gold/10"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ delay: 0.2 }}
            >
              <div className="flex items-center gap-3 mb-6">
                <div className="w-8 h-8 bg-gold/20 rounded-lg flex items-center justify-center">
                  <i className="ri-receipt-line text-gold"></i>
                </div>
                <h3 className="font-syncopate text-sm text-[#F8F4F0] font-bold">Order Summary</h3>
              </div>

              <div className="space-y-4 mb-6 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                {activeOrder.items.map((item, index) => (
                  <div key={index} className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white/5 rounded-xl border border-white/10 overflow-hidden flex-shrink-0 relative">
                      {item.isSprite ? (
                        <SpriteImage imageId={item.image} className="w-full h-full object-cover" cover={true} />
                      ) : (
                        <ResponsiveImage src={item.image} alt={item.name} className="w-full h-full object-cover" sizes="48px" />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-outfit text-sm text-[#F8F4F0] truncate font-medium">{item.name}</p>
                      <p className="font-outfit text-xs text-[#F8F4F0]/40">{item.size} × {item.quantity}</p>
                    </div>
                    <p className="font-outfit text-sm text-gold">₹{item.price * item.quantity}</p>
                  </div>
                ))}
              </div>

              <div className="pt-4 border-t border-white/5 flex justify-between items-center">
                <span className="font-outfit text-sm text-[#F8F4F0]/60">Total Amount Paid</span>
                <span className="font-syncopate text-lg text-gold font-bold">₹{activeOrder.totalAmount}</span>
              </div>
            </motion.div>

            {/* Facts Carousel */}
            <AnimatePresence mode="wait">
              <motion.div
                key={currentFact}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="glass-panel-strong rounded-2xl p-6 border-l-4 border-gold italic text-center"
              >
                <p className="font-outfit text-sm text-[#F8F4F0]/80 leading-relaxed">
                  "{foodFacts[currentFact]}"
                </p>
              </motion.div>
            </AnimatePresence>

            {/* Contact info */}
            <div className="space-y-3">
              {activeOrder.status !== 'placed' && activeOrder.status !== 'preparing' && (
                <motion.div
                  className="flex items-center justify-between p-4 bg-gold rounded-2xl cursor-pointer hover:bg-gold/90 transition-colors"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                >
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-obsidian/20 rounded-full flex items-center justify-center">
                      <i className="ri-user-star-line text-obsidian text-xl"></i>
                    </div>
                    <div>
                      <p className="font-outfit text-obsidian font-bold text-sm">Call Rider</p>
                      <p className="font-outfit text-obsidian/60 text-xs">Arjun Sharma</p>
                    </div>
                  </div>
                  <a href="tel:123" className="w-10 h-10 bg-obsidian rounded-full flex items-center justify-center text-gold shadow-lg hover:scale-105 transition-transform">
                    <i className="ri-phone-fill text-lg"></i>
                  </a>
                </motion.div>
              )}

              <div className="flex items-center justify-between p-4 bg-white/5 border border-white/10 rounded-2xl cursor-pointer hover:bg-white/10 transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-gold/10 rounded-full flex items-center justify-center border border-gold/20">
                    <i className="ri-store-2-line text-gold text-xl"></i>
                  </div>
                  <div>
                    <p className="font-outfit text-[#F8F4F0] font-bold text-sm">Call Store</p>
                    <p className="font-outfit text-[#F8F4F0]/60 text-xs">{activeOrder.restaurant.name}</p>
                  </div>
                </div>
                <a href="tel:123" className="w-10 h-10 bg-gold rounded-full flex items-center justify-center text-obsidian shadow-lg hover:scale-105 transition-transform">
                  <i className="ri-phone-fill text-lg"></i>
                </a>
              </div>

              <div className="flex items-center justify-center gap-2 pt-6 text-[#F8F4F0]/40 font-outfit text-xs">
                <i className="ri-shield-check-line text-gold text-lg"></i>
                <span>Secured by The Chocolate Room Tracking System</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
